(()=>{const A='#c69b72',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#0001;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 14px ${A}}.fx-orb{position:fixed;border-radius:50%;pointer-events:none;filter:blur(85px);opacity:.12;z-index:-1}.fx-orb.a{width:360px;height:360px;left:-140px;top:15%;background:${A};animation:drift 14s ease-in-out infinite}.fx-orb.b{width:320px;height:320px;right:-130px;bottom:10%;background:#8c6f57;animation:drift 18s ease-in-out infinite reverse}.fxr{opacity:0;transform:translateY(40px);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.timeline .reel-wrap{position:relative}.developed{transition:box-shadow .4s}.future-saved:after{content:'∞';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font:180px 'Playfair Display';color:${A};text-shadow:0 0 50px #c69b7266;animation:future .95s ease both}@keyframes drift{50%{transform:translate(80px,-45px)}}@keyframes future{0%{opacity:0;transform:scale(.6)}50%{opacity:1;transform:scale(1.08)}100%{opacity:0;transform:scale(1.3)}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(c=>{const o=document.createElement('div');o.className='fx-orb '+c;b.appendChild(o)});document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();